import { useEffect, useState } from "react";

export function useLookupOptions(fetcher, mapper) {
  const [options, setOptions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    let isCurrent = true;

    setIsLoading(true);
    setError(null);

    fetcher()
      .then((response) => {
        if (!isCurrent) return;

        const data = response?.data;

        // Your department API returns:
        // { success: true, total: ..., departments: [...] }

        let list = [];

        if (Array.isArray(data)) {
          list = data;
        } else if (Array.isArray(data?.departments)) {
          list = data.departments;
        } else if (Array.isArray(data?.data)) {
          list = data.data;
        }

        setOptions(list.map(mapper));
      })
      .catch((err) => {
        if (!isCurrent) return;

        console.error("Failed to load lookup options:", err);
        setError(err);
        setOptions([]);
      })
      .finally(() => {
        if (isCurrent) {
          setIsLoading(false);
        }
      });

    return () => {
      isCurrent = false;
    };
  }, [fetcher, mapper]);

  return {
    options,
    isLoading,
    error
  };
}
